// AI Agent Tool: search_code
const pattern = $input.item.json.pattern;
const fileTypes = $input.item.json.fileTypes || [];

// Get site info - try multiple paths to find it
let site;
try {
  site = $('Merge Files').item.json.site;
} catch (e) {
  // Fallback: try to get from input
  site = $input.item.json.site || {};
}

const owner = site.owner;
const repo = site.repo;

if (!owner || !repo) {
  return {
    json: {
      success: false,
      error: 'Missing repository information (owner/repo)',
      matches: []
    }
  };
}

// Build file extension filter
let fileExtension = '';
if (fileTypes && fileTypes.length > 0) {
  fileExtension = fileTypes.map(t => `+extension:${t}`).join('');
}

// Build GitHub search query
const query = `${pattern}+repo:${owner}/${repo}${fileExtension}`;

try {
  // Call GitHub API
  const response = await fetch(`https://api.github.com/search/code?q=${encodeURIComponent(query)}&per_page=50`, {
    headers: {
      'Authorization': `Bearer ${$env.GITHUB_TOKEN}`,
      'Accept': 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2022-11-28'
    }
  });

  const data = await response.json();

  // Format results
  if (!data || !data.items) {
    return {
      json: {
        success: true,
        matches: [],
        message: 'No matches found'
      }
    };
  }

  const matches = data.items.map(item => ({
    path: item.path,
    repository: item.repository?.full_name || 'unknown',
    url: item.html_url
  }));

  return {
    json: {
      success: true,
      matches: matches,
      total: data.total_count || 0,
      message: `Found ${matches.length} matches in ${matches.length} files`,
      files: matches.map(m => m.path)
    }
  };
} catch (error) {
  return {
    json: {
      success: false,
      error: error.message,
      matches: []
    }
  };
}
